# Generated by packaging/homebrew-formula.sh in adriandeleon/jkit; edits here are overwritten each release.
class Jkit < Formula
  desc "Installs and switches JDKs, Maven, Gradle and sbt"
  homepage "https://jkit-project.dev"
  # stated, not scanned from the URL: "jkit-0.3.0-linux-aarch64" holds other numbers too
  version "0.6.0"
  # jkit's own code is MIT; the binary also carries the libraries and Java runtime parts listed
  # in THIRD-PARTY-NOTICES (the main licenses; the notices file has every one)
  license all_of: [
    "MIT",
    "Apache-2.0",
    "BSD-2-Clause",
    "BSD-3-Clause",
    "BSL-1.0",
    "CC0-1.0",
    "ICU",
    "MPL-2.0",
    "Unicode-3.0",
    "W3C",
    "Zlib",
    { "GPL-2.0-only" => { with: "Classpath-exception-2.0" } },
  ]

  on_macos do
    depends_on macos: :sonoma

    on_arm do
      url "https://github.com/adriandeleon/jkit/releases/download/v0.6.0/jkit-0.6.0-macos-aarch64.tar.gz"
      sha256 "a5d87d504f12bfc118e74fb1ebf0414949709c7576f620cabbc8420635213b05"
    end
    on_intel do
      url "https://github.com/adriandeleon/jkit/releases/download/v0.6.0/jkit-0.6.0-macos-x64.tar.gz"
      sha256 "f9895f6f06584140b15c65e8281f8961ee3bbe3f4eb8c4737803fddb05f12b43"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/adriandeleon/jkit/releases/download/v0.6.0/jkit-0.6.0-linux-aarch64.tar.gz"
      sha256 "42a0b1c673a5e4094f1e03efe2e13787b73fcb478926da3fba59d5489cf79b75"
    end
    on_intel do
      url "https://github.com/adriandeleon/jkit/releases/download/v0.6.0/jkit-0.6.0-linux-x64.tar.gz"
      sha256 "b6877213a7afa5269c7bd7bf98d5f17dac7f5691581c8366c73eb698a19bfa00"
    end
  end

  def install
    bin.install "jkit"
    prefix.install "LICENSE", "THIRD-PARTY-NOTICES"
    generate_completions_from_executable(bin/"jkit", "completion", shells: [:bash])
  end

  def caveats
    <<~EOS
      To switch versions with `jkit use` and on cd, add the shell hook:
        jkit hook --install --auto-switch
    EOS
  end

  test do
    assert_equal "jkit #{version}", shell_output("#{bin}/jkit --version").strip
    ENV["JKIT_HOME"] = testpath/"jkit-home"
    assert_match "schemaVersion", shell_output("#{bin}/jkit list --json")
  end
end
